const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgPaths[n]||svgPaths.foods}</svg>`;
const food=id=>foods.find(f=>f.id===id),uid=()=>globalThis.crypto?.randomUUID?.()||'demo-'+Math.random().toString(36).slice(2),fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'}),before=n=>{const d=new Date(TODAY+'T12:00:00');d.setDate(d.getDate()-n);return PrikormModel.localDate(d);};
function ageMonths(dob){if(!dob)return null;const b=new Date(dob+'T12:00:00'),t=new Date(TODAY+'T12:00:00');return (t.getFullYear()-b.getFullYear())*12+t.getMonth()-b.getMonth()-(t.getDate()<b.getDate()?1:0);}
const notice=(text,kind='')=>`<div class="notice ${kind}">${text}</div>`;
