const pageNames={"today":"Сегодня","diary":"Дневник","more":"Памятка","plan":"План врача","profile":"Профиль","patients":"Пациенты","newPatient":"Новый пациент","settings":"Данные и установка","report":"Отчёт для врача","help":"При реакции","about":"О приложении","foods":"Продукты","allergens":"Аллергены","food":"Продукт","meal":"Запись приёма","symptom":"Запись симптома","readiness":"Что важно перед началом","safe":"Безопасные формы и текстуры","nutrition":"Железо, разнообразие и аппетит","sources":"Источники","observation":"Как наблюдать за продуктами"};
let navigationPath=[],navigationPatient=null,returnRequested=false;
function rememberNavigation(next,patient){const returning=returnRequested;returnRequested=false;if(patient!==navigationPatient){navigationPath=[];navigationPatient=patient;}if(navigationPath.at(-1)===next)return;if(returning&&navigationPath.at(-2)===next)navigationPath.pop();else{navigationPath.push(next);if(navigationPath.length>64)navigationPath.shift();}}
function backDestination(fallback){return navigationPath.length>1?navigationPath.at(-2):fallback;}
function returnLabel(dialog){const previous=[...document.querySelectorAll('dialog[open]')].filter(node=>node!==dialog).at(-1);return '← '+(previous?.querySelector('.family-about-bar h2')?.textContent||pageNames[view]||'Сегодня');}
const back=(fallback='today')=>{const target=backDestination(fallback);return `<button class="link back" data-go="${target}" data-back>← ${pageNames[target]||'Сегодня'}</button>`;};
const input=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${type==='text'?'maxlength="300"':''} ${extra}></label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;
function ruleCard(id,open=false){const r=rules.get(id);return `<details ${open?'open':''}><summary>${esc(r.title)}</summary><p>${esc(r.parent)}</p><p class="small">${esc(r.evidence)}</p><p class="rule-ref">${r.sources.map(s=>{const x=SPEC.sources.find(x=>x.id===s);return `<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.short)}</a>`;}).join(' · ')}</p></details>`;}
let profiles=[],active=0,p,view='today',catalogFilter='all',catalogGroup='all',search='',selectedFood='egg',foodOrigin='foods',selectedDay=TODAY,editing=null,photoDraft=null,photoInclude=false,toastTimer,dirty=false,triageAcknowledged='',iconData='./assets/icon-rounded-512.png';
function hasSymptoms(m){return p.symptoms.some(s=>s.mealId===m.id);}
function eaten(){return p.meals.filter(m=>m.kind==='eaten');}
function knownAllergens(m){return [...new Set(m.foodIds.flatMap(id=>food(id)?.allergens||[]))];}
function seenAllergens(){return new Set(eaten().flatMap(knownAllergens));}
function allergenContext(a){
 const names={severeEczema:'тяжёлый атопический дерматит',eggAllergy:'установленная аллергия на яйцо',milkAllergy:'установленная аллергия на белки коровьего молока',peanutAllergy:'установленная аллергия на арахис',peanutReaction:'предыдущая реакция на арахис',complex:'особенности здоровья, требующие индивидуального плана'};
 const keys=a==='peanut'?['severeEczema','eggAllergy','peanutAllergy','peanutReaction','complex']:(a==='egg'?['eggAllergy']:a==='milk'?['milkAllergy']:[]);
 const yes=keys.filter(k=>p.risks[k]==='yes');if(a==='peanut'&&p.risks.milkAllergy==='yes')yes.push('milkAllergy');
 return {risk:yes.length>0,unknown:keys.some(k=>!['yes','no'].includes(p.risks[k])),reasons:yes.map(k=>names[k])};
}
function allergenAdvice(a){const c=allergenContext(a),name=allergenNames[a];if(c.risk)return notice('<strong>'+name+': перед введением обсудите план с врачом.</strong> В профиле отмечено: '+c.reasons.join(', ')+'. '+(a==='peanut'?'Способ и место введения определяют индивидуально.':'Общая памятка не разрешает повторную пробу при установленной аллергии.'),'warn');if(c.unknown)return notice(name+': сведения профиля не уточнены. Заполните анкету; эта отметка сама по себе не означает аллергию или высокий риск. При прежней реакции или сомнениях сначала обсудите введение с врачом.');return '';}
function peanutRisk(){const c=allergenContext('peanut');return c.risk||c.unknown;}
function personalized(){return p.risks.complex!=='no';}
function productState(f){return PrikormModel.foodStatus(p,f);}
function foodMark(f){const s=productState(f);return `<span class="food-mark ${s.tone}" aria-hidden="true">${s.symbol}</span>`;}
function lastFoodMeal(f){return eaten().filter(m=>m.foodIds.includes(f.id)).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))[0];}
function foodRepeatNote(f){const last=lastFoodMeal(f);if(['Специи','Масла','Другие продукты','Молочное вскармливание'].includes(f.group)||productState(f).tone!=='green'||!last||last.date>=before(7)||personalized()||ageMonths(p.dob)===null||ageMonths(p.dob)<6||p.doctorFoods.some(d=>d.foodId===f.id)||f.allergens.some(a=>['egg','milk','peanut'].includes(a)&&(allergenContext(a).risk||allergenContext(a).unknown)))return '';return 'За последнюю неделю нет записи. Если продукт остаётся в согласованном рационе, предлагайте его регулярно; практический ориентир — не реже одного раза в неделю. Возможно, вы давали его без отметки.';}
function foodsToRepeat(){return availableFoods.filter(f=>foodRepeatNote(f)).sort((a,b)=>lastFoodMeal(a).date.localeCompare(lastFoodMeal(b).date)||a.name.localeCompare(b.name,'ru'));}
function repeatFoodRow(f){const last=lastFoodMeal(f);return `<div class="repeat-food" data-repeat-food="${f.id}"><button class="food-row" data-food="${f.id}"><span class="food-symbol">${foodArt(f)}</span><span class="food-info"><strong>${esc(f.name)}</strong><small>Последняя запись: ${fmt(last.date)}</small></span>${foodMark(f)}<span class="chevron" aria-hidden="true">›</span></button><button class="link repeat-record" data-record-food="${f.id}">Записать употребление</button></div>`;}
function repeatFoodsCard(){const items=foodsToRepeat();if(!items.length)return '';return `<section class="card repeat-foods" aria-labelledby="repeat-foods-title"><div class="row"><h3 id="repeat-foods-title">Сохраняем продукты в рационе</h3><span class="pill">${items.length}</span></div><p>Эти продукты уже употреблялись без отмеченных реакций или с уточнением врача, но новых записей нет больше недели.</p><p class="small">Практический ориентир для поддержания переносимости — предлагать уже введённый продукт не реже одного раза в неделю, если врач не назначил иначе. Минимальная частота, гарантирующая профилактику аллергии, неизвестна.</p>${items.slice(0,3).map(repeatFoodRow).join('')}${items.length>3?'<details class="repeat-more"><summary>Показать остальные ('+(items.length-3)+')</summary>'+items.slice(3).map(repeatFoodRow).join('')+'</details>':''}<p class="small">Возможно, ребёнок ел продукт без записи. Отметьте фактическую дату — напоминание пересчитается. При новых симптомах сначала обсудите действия с врачом.</p></section>`;}
function foodReviewForm(f){const review=p.foodReviews?.find(r=>r.foodId===f.id),linked=PrikormModel.relatedSymptoms(p,f.id);return `<details class="food-review"><summary>Уточнить отметку после консультации</summary><p class="small">Если врач исключил связь прежних симптомов с этим продуктом, внесите заключение. Исходные наблюдения останутся в дневнике. Новые симптомы или изменения в связанных записях потребуют отдельной оценки.</p>${!linked.length&&!review?'<p class="small">Связанных записей о симптомах нет. Уточнить результат употребления можно в истории продукта ниже.</p>':`<form id="food-review-form">${select('Отметка','reviewMode',[['auto','По записям дневника'],['excluded','Связь исключена врачом']],review?'excluded':'auto')}${input('Дата заключения','reviewDate',review?.date||TODAY,'date',`max="${TODAY}" ${p.dob?'min="'+p.dob+'"':''}`)}<label class="field">Врач и содержание заключения<textarea name="reviewNote" maxlength="1000" rows="3">${esc(review?.note||'')}</textarea></label><p class="small">Уточнение относится только к этому продукту и перечисленным наблюдениям: ${linked.length?linked.map(x=>fmt(x.date)+' · '+x.codes.map(c=>symptomNames[c]).join(', ')).map(esc).join('; '):'прежние записи удалены'}. Наблюдение с неуточнённым результатом и ограничения врача сохраняются. Снятие ограничения в плане или аллергии в профиле внесите отдельно по заключению врача.</p><p class="error" id="food-review-error" role="alert"></p><button type="submit" class="wide">Сохранить уточнение</button></form>`}</details>`;}
function reminderAllowed(a){if(['mustard','celery','lupin','molluscs','coconut','pineNut'].includes(a))return false;const rows=eaten().filter(m=>knownAllergens(m).includes(a));if(!rows.length||groupFoods({keys:[a]}).some(f=>PrikormModel.unresolvedFoodSymptoms(p,f.id).length)||rows.some(m=>m.result!=='none')||personalized()||ageMonths(p.dob)===null||ageMonths(p.dob)<6)return false;if(a==='peanut'&&peanutRisk())return false;if(a==='egg'&&p.risks.eggAllergy!=='no'||a==='milk'&&p.risks.milkAllergy!=='no')return false;if(p.doctorFoods.some(d=>food(d.foodId)?.allergens.includes(a)))return false;return true;}
function dayState(date){if(p.symptoms.some(s=>s.date===date))return 'symptom';const rows=p.meals.filter(m=>m.date===date);if(rows.some(m=>m.kind==='eaten'&&(m.result!=='none'||m.unknown)))return 'pending';if(rows.some(m=>m.kind==='eaten'))return 'ok';if(rows.length)return 'skip';return 'empty';}
const marks={ok:'✓',pending:'◌',symptom:'!',skip:'—',empty:'·'},dayNames={ok:'записано употребление без отмеченных симптомов',pending:'наблюдение или результат не уточнён',symptom:'есть запись о симптомах',skip:'приём не состоялся',empty:'нет записи'};
function foodRow(f){const s=productState(f);return `<button class="food-row" data-food="${f.id}"><span class="food-symbol">${foodArt(f)}</span><span class="food-info"><strong>${catalogFilter==='iron'&&f.ironLabel?f.ironLabel:f.name}</strong><small>${s.label}</small>${lastFoodMeal(f)?'<small>Последняя запись: '+fmt(lastFoodMeal(f).date)+'</small>':''}${foodRepeatNote(f)?'<small class="food-repeat">Давно не отмечали · напоминание в карточке</small>':''}</span>${foodMark(f)}<span class="chevron" aria-hidden="true">›</span></button>`;}
function ageNotice(){const age=ageMonths(p.dob);if(age===null)return notice('Укажите дату рождения, чтобы видеть подходящие возрастные сведения. Дневник уже доступен.');if(age<4)return notice('<strong>Пока знакомимся с информацией.</strong> Прикорм не вводят раньше 4 полных месяцев. Можно изучить признаки готовности и безопасную подачу. Запись уже произошедшего доступна.','warn');if(age<6)return notice('<strong>Начало до 6 месяцев обсудите с педиатром.</strong> Возраст и отметки в списке признаков готовности сами по себе не являются разрешением начать.','warn');if(personalized())return notice('При сложном медицинском анамнезе нужен индивидуальный план. Здесь доступны дневник и сведения для обсуждения с врачом.','warn');return '';}
const screens={};
screens.today=()=>{const groups=[...new Set(eaten().filter(m=>m.date>=before(6)).flatMap(m=>m.foodIds.map(id=>food(id)?.group).filter(Boolean)))],age=ageMonths(p.dob),early=age===null||age<6;const recent=eaten().slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).slice(0,2);return header('Знакомимся с едой',early?'Маленькие шаги.<br>Без спешки.':'Новые вкусы.<br>В своём темпе.')+ageNotice()+`<button class="link" data-go="readiness">Что важно перед началом</button><section class="hero"><div class="hero-mark"><span class="pill">${early?'Готовимся вместе':'Сегодня, '+fmt(TODAY)}</span></div><h2>${early?'Готовность к прикорму важнее, чем возраст':'Предлагаем спокойно.<br>Замечаем важное.'}</h2><p>${early?'Удержание головы, сидение с поддержкой и возможность глотать — ориентиры для разговора с педиатром.':'Прикорм дополняет грудное молоко или смесь. Не заставляйте доедать: аппетит может меняться.'}</p><button class="primary wide" data-action="new-meal">Записать приём пищи</button><button class="link wide" data-go="${early?'readiness':'safe'}">${early?'Признаки готовности':'Безопасная подача продуктов'}</button></section>${repeatFoodsCard()}<div class="mini"><button data-go="foods">${icon('foods')}<strong>Продукты</strong><small>Состав и безопасная форма</small></button><button data-action="new-symptom">${icon('symptom')}<strong>Новый симптом</strong><small>Можно без записи о еде</small></button></div>${p.symptoms.length?notice('В дневнике есть симптомы. Это не диагноз и не доказательство связи с продуктом. Сохраните подробности для врача.','warn'):''}<section class="card"><div class="row"><h3>Последние 7 дней</h3><button class="link" data-go="diary">Все записи</button></div><div class="week">${Array.from({length:7},(_,i)=>{const d=before(6-i),s=dayState(d);return `<button class="day" data-day="${d}" data-status="${s}" aria-pressed="${d===selectedDay}" aria-label="${fmt(d)}: ${dayNames[s]}"><small>${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short'})}</small>${+d.slice(-2)}<b>${marks[s]}</b></button>`;}).join('')}</div><p class="legend">✓ запись без симптомов · ! симптомы · ◌ наблюдение / неизвестно · — без приёма · · нет записи</p><p id="day-detail" class="small" style="margin-top:12px">${fmt(selectedDay)}: ${dayNames[dayState(selectedDay)]}</p></section><section class="card"><div class="row"><h3>Разнообразие недели</h3><span class="pill neutral">Без обязательной нормы</span></div><div class="group-tags">${['Овощи','Фрукты и ягоды','Крупы, хлеб и клубнеплоды','Мясо','Рыба','Бобовые','Яйца','Молочные продукты'].map(g=>`<span class="group-tag ${groups.includes(g)?'present':''}">${groups.includes(g)?'✓ ':''}${g}</span>`).join('')}</div><p class="small" style="margin-top:12px">Показаны только записи об употреблении. Пустая группа не означает дефицит или отсутствие продукта в рационе.</p><button class="link" data-go="nutrition">Источники железа и аппетит</button></section><section class="card"><div class="row"><h3>Недавно в дневнике</h3><button class="link" data-go="allergens">Аллергены</button></div>${recent.length?[...new Set(recent.flatMap(m=>m.foodIds))].slice(0,3).map(id=>foodRow(food(id))).join(''):'<p class="muted" style="margin-top:12px">Пока нет записей об употреблении.</p>'}</section><button class="wide" data-go="report">Подготовить отчёт для врача</button>`;};
screens.readiness=()=>back('today','Сегодня')+header('Перед началом','Готовимся знакомиться<br>с едой.','Чек-лист помогает наблюдать, а не выдаёт медицинский допуск.')+ageNotice()+`<section class="card"><h3>Что уже замечаете?</h3>${Object.entries({head:'Устойчиво удерживает голову',sit:'Сидит с поддержкой',coordinate:'Координирует движения рук и рта, интересуется едой',swallow:'Способен проглатывать пищу; выталкивающий рефлекс языка угас — ребёнок не выталкивает пищу языком'}).map(([k,v])=>`<label class="check"><input type="checkbox" data-ready="${k}" ${p.ready[k]?'checked':''}><span>${v}</span></label>`).join('')}<p class="small">Галочки — наблюдения семьи. При сомнениях обсудите начало с педиатром. Зубы и руки во рту сами по себе не определяют готовность.</p></section>${['C01','C03','C04','C07','C30'].map(id=>ruleCard(id)).join('')}<details id="choking-help"><summary>Правила оказания помощи, если ребёнок подавился</summary>${chokingHelpContent()}</details>${back('today')}`;
screens.foods=()=>header('Продукты и подача','Знакомство<br>без гонки.','У каждого продукта — своя форма и своя история.')+`<p class="small">${availableFoods.length} продуктов · каталог продуктов</p><label class="field">Найти продукт<input type="search" id="food-search" placeholder="Например, кабачок или говядина" value="${esc(search)}"></label><label class="field">Категория<select id="food-group"><option value="all">Все категории</option>${foodGroups.map(g=>`<option ${catalogGroup===g?'selected':''}>${g}</option>`).join('')}</select></label><div class="segmented" aria-label="Фильтр продуктов">${[['all','Все'],['iron','Богатые железом'],['recorded','В дневнике']].map(([v,t])=>`<button data-filter="${v}" aria-pressed="${catalogFilter===v}">${t}</button>`).join('')}</div><p class="small food-legend">✓ — ел без реакций по записям или после уточнения врача; ! — симптомы или ограничение; ◌ — наблюдение; · — нет записи. Нажмите на продукт, чтобы уточнить отметку. Отметки не устанавливают диагноз.</p><div id="food-list">${catalogRows()}</div><p class="small" style="margin-top:15px">Каталог — справочник, а не список обязательных проб. Известную аллергию и назначения учитывайте вместе с врачом. Масла и специи показаны как ингредиенты блюд.</p>`;
function catalogRows(){
 const rows=availableFoods.filter(f=>matchesFood(f,search)&&(catalogGroup==='all'||f.group===catalogGroup)&&(catalogFilter==='all'||catalogFilter==='iron'&&f.iron||catalogFilter==='recorded'&&eaten().some(m=>m.foodIds.includes(f.id))));
 const groups=(items,level=2)=>foodGroups.map(g=>{const list=items.filter(f=>f.group===g);return list.length?`<section class="catalog-group"><h${level}>${g}</h${level}><div class="card">${list.map(foodRow).join('')}</div></section>`:'';}).join('');
 const intro=catalogFilter==='iron'?'<p class="small">Для регулярного рациона: каша, обогащённая железом, мясо и бобовые. Ниже — дополнительные продукты для разнообразия. Не все продукты этой подборки богаты железом в обычной детской порции: рыба, креветки, яйца и зелень не равноценны основным источникам. Учитывайте порцию, приготовление и усвояемость.</p>':'';
 const content=catalogFilter==='iron'?[['main','Основные источники железа'],['additional','Дополнительные продукты']].map(([role,title])=>{const items=rows.filter(f=>f.ironRole===role);return items.length?`<section class="iron-tier" data-iron-role="${role}"><h2>${title}</h2>${groups(items,3)}</section>`:'';}).join(''):groups(rows);
 return intro+`<p class="small catalog-count" role="status">Найдено: ${rows.length}</p>`+(rows.length?content:'<div class="empty">Нет продуктов по выбранным условиям. Попробуйте другую категорию или название.</div>');
}
screens.food=()=>{const f=food(selectedFood),s=productState(f),doctor=p.doctorFoods.find(d=>d.foodId===f.id),rows=eaten().filter(m=>m.foodIds.includes(f.id));return back(foodOrigin,foodOrigin==='allergens'?'Аллергены':'Продукты')+header(f.group,f.name)+`<div class="food-detail-art">${foodArt(f,true)}</div>`+`<div class="food-status-detail">${foodMark(f)}<span>${s.label}</span></div>${lastFoodMeal(f)?'<p class="small">Последняя запись об употреблении: '+fmt(lastFoodMeal(f).date)+'</p>':''}${foodRepeatNote(f)?notice(esc(foodRepeatNote(f))+'<p class="small">Минимальная частота, гарантирующая профилактику аллергии, неизвестна.</p>'): ''}${foodReviewForm(f)}`+ageNotice()+(doctor?notice('<strong>Сведения из плана врача</strong><p>'+esc(doctor.note)+'</p>',doctor.status==='avoid'?'warn':''):'')+f.allergens.filter(a=>['peanut','egg','milk'].includes(a)).map(allergenAdvice).join('')+(f.id==='honey'&&(ageMonths(p.dob)===null||ageMonths(p.dob)<12)?notice('<strong>Мёд до года не дают.</strong> Это касается и мёда в составе блюд. Запись уже произошедшего употребления остаётся доступной.','danger'):'')+(f.iron?`<section class="card"><h3>Железо в рационе</h3><p>${esc(f.ironNote)}</p><p class="small">Подборка помогает разнообразить рацион; дневник не определяет обеспеченность железом и не назначает лечение дефицита.</p></section>`:'')+`<section class="card"><h3>Безопасная форма</h3><p>${f.textureRules}</p><p class="small">Иллюстрация показывает продукт, а не форму подачи ребёнку.</p><p class="small">Ребёнок сидит, взрослый постоянно наблюдает. Универсальный размер кусочка не назначается.</p></section><section class="card"><h3>Что отражается в дневнике</h3><p>${f.allergens.length?f.allergens.map(a=>allergenNames[a]).join(', '):'Для выбранного продукта не указан распространённый аллерген. Это не гарантирует отсутствие любой аллергии.'}</p>${f.compositionNote?'<p class="small">'+esc(f.compositionNote)+'</p>':''}${f.id==='wheat'?'<p class="small">Пшеница и аллергия на неё учитываются отдельно от глютена и целиакии.</p>':''}${f.id==='iron-cereal'?'<p class="small">Злак, молоко и другие компоненты отметьте отдельно по этикетке.</p>':''}</section><button class="primary wide" data-record-food="${f.id}">Записать фактически съеденное</button><p class="small" style="margin-top:12px">Наличие кнопки не является рекомендацией предложить продукт.</p><h3 class="tabs-title">История продукта</h3>${rows.length?rows.slice().reverse().map(mealCard).join(''):empty('Пока нет записей об употреблении.')}<h3 class="tabs-title">Подробнее</h3>${f.refs.map(id=>ruleCard(id)).join('')}`;};
function empty(t){return `<div class="empty">${t}</div>`;}
const allergenGroups=[
 {id:'egg',name:'Яйцо',keys:['egg']},
 {id:'milk',name:'Молоко',keys:['milk']},
 {id:'wheat',name:'Пшеница',keys:['wheat']},
 {id:'fish',name:'Рыба',keys:['fish'],separate:true},
 {id:'tree-nuts',name:'Орехи',keys:['walnut','almond','cashew','hazelnut','pecan','pistachio','pineNut','coconut','brazilNut'],separate:true},
 {id:'shellfish',name:'Ракообразные',keys:['shellfish'],separate:true},
 {id:'molluscs',name:'Моллюски',keys:['molluscs'],separate:true},
 {id:'soy',name:'Соя',keys:['soy']},
 {id:'peanut',name:'Арахис',keys:['peanut']},
 {id:'sesame',name:'Кунжут',keys:['sesame']},
 {id:'fishRoe',name:'Рыбная икра',keys:['fishRoe']},
 {id:'celery',name:'Сельдерей',keys:['celery']},
 {id:'lupin',name:'Люпин',keys:['lupin']}
];
function groupFoods(g){return foods.filter(f=>f.allergens.some(a=>g.keys.includes(a)));}
function groupMeals(g){return eaten().filter(m=>knownAllergens(m).some(a=>g.keys.includes(a)));}
function groupContext(g){const rows=groupMeals(g),items=groupFoods(g),sym=items.some(f=>PrikormModel.unresolvedFoodSymptoms(p,f.id).length),plans=p.doctorFoods.filter(d=>items.some(f=>f.id===d.foodId));return {sym,plans,...allergenContext(g.id)};}
function allergenProductRow(f){const plan=p.doctorFoods.find(d=>d.foodId===f.id);return `<div class="allergen-product" data-allergen-food="${f.id}">${foodRow(f)}${plan?'<p class="small product-context">Из плана врача: '+esc(plan.note)+'</p>':''}${foodRepeatNote(f)?'<p class="small product-context">'+esc(foodRepeatNote(f))+' Минимальная частота, гарантирующая профилактику аллергии, неизвестна.</p>':''}</div>`;}
function allergenGroupCard(g){const rows=groupMeals(g),ctx=groupContext(g);return `<details class="allergen-group" data-allergen-group="${g.id}"><summary><span class="allergen-group-name">${g.name}</span><span class="allergen-group-state">${rows.length?'Есть записи':'Пока нет записей'}</span>${ctx.sym||ctx.plans.length||ctx.risk||ctx.unknown?'<span class="allergen-context">'+(ctx.sym?'Есть наблюдения о симптомах':ctx.plans.length?'Есть рекомендации врача':ctx.risk?'Перед введением — обсудить с врачом':'Сведения профиля не уточнены')+'</span>':''}</summary><div class="allergen-group-body">${g.separate?'<p class="small">Каждый продукт учитывается отдельно. Запись об одном виде не переносится на остальные.</p>':''}${ctx.sym?notice('В дневнике есть связанные наблюдения о симптомах. Они не устанавливают причину реакции. Не повторяйте подозреваемый продукт до оценки врачом.','warn'):''}${allergenAdvice(g.id)}${g.id==='tree-nuts'?'<p class="small">Кокос и кедровые орешки включены сюда для удобства поиска. Ботанически кокос — плод-костянка, кедровые орешки — семена сосны. Записи по ним отдельные.</p>':''}${g.id==='fishRoe'?'<p class="small">Икра учитывается отдельно от мяса рыбы: состав аллергенных белков различается. Переносимость рыбы не подтверждает переносимость икры и наоборот. При записи укажите вид рыбы и состав икры по этикетке.</p>':''}${g.id==='fish'?'<p class="small">Возможны реакции на один или несколько видов рыбы, в том числе перекрёстные. Здесь перечислены распространённые рыночные названия; точный вид уточняйте по этикетке.</p>':''}${groupFoods(g).filter(f=>!f.retired).length>8?`<label class="field">Найти в группе<input type="search" data-group-search="${g.id}" placeholder="Например, ${g.id==='fishRoe'?'<p class="small">Икра учитывается отдельно от мяса рыбы: состав аллергенных белков различается. Переносимость рыбы не подтверждает переносимость икры и наоборот. При записи укажите вид рыбы и состав икры по этикетке.</p>':''}${g.id==='fish'?'треска':'продукт'}" aria-label="Поиск: ${g.name}"></label><p class="small" data-group-count="${g.id}" role="status">В группе: ${groupFoods(g).filter(f=>!f.retired).length}</p>`:''}${groupFoods(g).filter(f=>!f.retired).map(allergenProductRow).join('')}${g.separate?'<p class="small group-footnote">Если конкретного вида нет в каталоге, укажите его в названии блюда или комментарии. Такая запись не присваивается другим видам автоматически.</p>':''}</div></details>`;}
screens.allergens=()=>header('Аллергены','Знакомство<br>с аллергенами.','Не обязательный список проб, а история знакомства с продуктами.')+`<div class="allergen-groups">${allergenGroups.map(allergenGroupCard).join('')}</div>${eaten().some(m=>m.unknown)?'<p class="small composition-status">Есть блюда с неуточнённым составом. Учитываются только известные ингредиенты.</p>':''}<details class="allergen-info"><summary>Что важно знать</summary><p>Здесь собраны записи о продуктах, которые могут вызывать аллергию. Это не обязательный список проб. Отметки дневника не подтверждают и не исключают аллергию.</p><p>«Есть записи» означает, что в дневнике отмечено употребление хотя бы одного продукта группы. Это не подтверждает переносимость всей группы. «Пока нет записей» не означает, что ребёнок никогда не ел этот продукт.</p><p>Объединение сделано для удобства просмотра. В карточках и отчёте сохраняются конкретные продукты, даты и наблюдения. Неизвестный состав не считается отсутствием аллергенов.</p><h3 class="tabs-title">Глютен и сульфиты</h3><p>Глютен не равнозначен аллергии на пшеницу. Сульфиты — пищевые добавки, а не отдельный продукт прикорма. Укажите сведения с этикетки в комментарии к блюду; приложение не предполагает их наличие во всех сухофруктах.</p><p>Сведения о горчице сохраняются в каталоге, записях и индивидуальном плане врача.</p>${ruleCard('C13')}${ruleCard('C15')}${ruleCard('C17')}${ruleCard('C18')}${ruleCard('C28')}${ruleCard('C24')}</details>`;
const resultText={none:'По отметке семьи — без симптомов',pending:'Наблюдение продолжается',unknown:'Результат не уточнён'},kindText={eaten:'Ел',offered:'Предложили',refused:'Отказался',skipped:'Приёма не было'};
function mealTitle(m){return m.dish||m.foodIds.map(id=>food(id)?.name).join(', ')||'Блюдо с неуточнённым составом';}
function mealCard(m,edit=true){return `<article class="entry ${hasSymptoms(m)?'symptom':''}"><div class="row"><span>${fmt(m.date)} · ${m.time}</span><span>${kindText[m.kind]}</span></div><h3>${esc(mealTitle(m))}</h3><p>${m.kind==='eaten'?hasSymptoms(m)?'Есть отдельная запись о симптомах':resultText[m.result]:'Употребление не засчитывается'}</p>${m.amount?'<p class="small">Количество: '+esc(m.amount)+'</p>':''}${m.texture?'<p class="small">Форма: '+esc(m.texture)+'</p>':''}${m.unknown?'<p class="small">Состав частично или полностью неизвестен.</p>':''}${m.note?'<p class="small">'+esc(m.note)+'</p>':''}${edit?`<button class="link" data-edit-meal="${m.id}">Уточнить запись</button>`:''}</article>`;}
function symptomCard(s,edit=true){const linked=p.meals.find(m=>m.id===s.mealId);return `<article class="entry symptom"><div class="row"><span>${fmt(s.date)} · ${s.time}</span><span>Симптомы</span></div><h3>${s.codes.map(k=>symptomNames[k]).join(', ')}</h3><p>${linked?'Указанный приём: '+esc(mealTitle(linked)):'Связь с приёмом пищи не указана'}</p><p class="small">${onsetText[s.onset]||'Время относительно еды не уточнено'}. Причина не установлена приложением.</p>${s.note?'<p class="small">'+esc(s.note)+'</p>':''}${s.photo&&(!edit&&photoInclude)?'<img class="report-photo" src="'+s.photo+'" alt="Фото, приложенное семьёй к записи симптомов">':s.photo?'<p class="small">К записи прикреплено фото.</p>':''}${edit?`<button class="link" data-edit-symptom="${s.id}">Уточнить симптомы</button>`:''}</article>`;}
screens.diary=()=>header('Записи семьи','Еда и наблюдения.<br>В одном месте.')+`<div class="toolbar"><button class="primary" data-action="new-meal">Записать приём</button><button data-action="new-symptom">Новый симптом</button></div><button class="primary wide" data-go="report">Отчёт для врача</button>${p.meals.length||p.symptoms.length?[...p.meals.map(m=>({date:m.date,time:m.time,html:mealCard(m)})),...p.symptoms.map(s=>({date:s.date,time:s.time,html:symptomCard(s)}))].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).map(x=>x.html).join(''):empty('Записей пока нет. Можно отметить еду или сохранить наблюдение без связи с продуктом.')}`;
let preselectedFood=null;
function mealKindField(m){return `<label class="field">Что произошло?<select name="kind" required>${m?.kind==='offered'?'<option value="" selected disabled>Уточните исход старой записи</option>':''}${Object.entries(kindText).filter(([key])=>key!=='offered').map(([key,label])=>`<option value="${key}" ${(m?.kind||'eaten')===key?'selected':''}>${label}</option>`).join('')}</select></label>${m?.kind==='offered'?'<p class="small">В старой записи отмечено только предложение еды. Перед сохранением уточните: ребёнок ел, отказался или приёма не было. Исходная запись сохранится, если выйти без изменений.</p>':''}`;}
function observationGuidance(){return '<p class="small observation-guidance">После первого употребления нового продукта продолжайте наблюдение в течение <strong>3–5 дней</strong>: отмечайте самочувствие, изменения кожи и пищеварения. Это практический период наблюдения за возможными отсроченными изменениями, а не срок, исключающий аллергию. При острых симптомах не ждите окончания этого периода — действуйте по плану помощи.</p>';}
screens.meal=()=>{const m=p.meals.find(m=>m.id===editing);return back('diary','К дневнику')+header('Фактически произошедшее',m?'Уточнить приём':'Что было на тарелке?','Можно записать даже то, что не планировали давать. Предупреждение не блокирует запись факта.')+`<form id="meal-form"><div class="grid2">${input('Дата','date',m?.date||TODAY,'date','required max="'+TODAY+'"')}${input('Время','time',m?.time||PrikormModel.localTime(),'time','required')}</div>${mealKindField(m)}${input('Название блюда (необязательно)','dish',m?.dish||'')}<label class="field" for="ingredient-search">Найти продукт или ингредиент<input type="search" id="ingredient-search" placeholder="Например, кабачок"></label><p class="small" id="ingredient-count" role="status"></p><div class="selector" aria-label="Продукты и известные ингредиенты">${foods.filter(f=>!f.retired||m?.foodIds.includes(f.id)).map(f=>`<label class="check ingredient-option" data-ingredient="${f.id}"><input type="checkbox" name="foodIds" value="${f.id}" ${(m?.foodIds||[preselectedFood]).includes(f.id)?'checked':''}>${foodArt(f)}<span>${f.name}${f.allergens.length?' · '+f.allergens.map(a=>allergenNames[a]).join(', '):''}</span></label>`).join('')}</div><label class="check"><input name="unknown" type="checkbox" ${m?.unknown?'checked':''}><span>Не весь состав известен</span></label><div id="meal-warnings" aria-live="polite"></div>${input('Фактически съеденное количество (необязательно)','amount',m?.amount||'','text','placeholder="Например, несколько ложек или не оценивали"')}${input('Как приготовили и подали','texture',m?.texture||'','text','placeholder="Форма, мягкость, состав"')}${select('Наблюдение после еды','result',Object.entries(resultText),m?.result||'unknown')}${observationGuidance()}<p class="small">Симптомы сохраняются отдельной записью. Неизвестный результат не считается отсутствием симптомов.</p><button type="button" class="link" data-go="help">Если появилась реакция</button><label class="field">Комментарий<textarea name="note" maxlength="1500">${esc(m?.note||'')}</textarea></label><p class="error" id="meal-error" role="alert"></p><button class="primary wide" type="submit">Сохранить запись</button></form>`;};
function mealWarnings(ids,unknown,kind){const a=[...new Set(ids.flatMap(id=>food(id).allergens))],seen=new Set(eaten().filter(m=>m.id!==editing).flatMap(knownAllergens)),fresh=a.filter(a=>!seen.has(a)),texts=[];if(fresh.length>1&&kind==='eaten')texts.push(notice('<strong>Несколько новых аллергенов в одном приёме.</strong> '+fresh.map(a=>allergenNames[a]).join(', ')+'. При первом знакомстве лучше один новый аллерген за приём, чтобы легче оценить возможную реакцию. Фактически съеденное всё равно можно записать.','warn'));if(unknown)texts.push(notice('Укажите известные ингредиенты. Остальной состав останется неизвестным; отсутствие аллергенов не предполагается.'));for(const key of a.filter(a=>['peanut','egg','milk'].includes(a))){const advice=allergenAdvice(key);if(advice)texts.push(advice);}if(ids.includes('honey')&&(ageMonths(p.dob)===null||ageMonths(p.dob)<12))texts.push(notice('<strong>Мёд до 12 месяцев не дают</strong> из-за риска ботулизма. Если это уже произошло, факт можно сохранить.','danger'));if(ids.includes('milk')&&(ageMonths(p.dob)===null||ageMonths(p.dob)<12))texts.push(notice('Коровье молоко до года не заменяет грудное молоко или смесь как основной напиток.'));for(const d of p.doctorFoods.filter(d=>d.status==='avoid'&&ids.includes(d.foodId)))texts.push(notice('Ограничение из плана врача: '+food(d.foodId).name+'. '+esc(d.note),'warn'));for(const f of ids.map(food))texts.push(`<details><summary>${f.name}: форма и приготовление</summary><p>${f.textureRules}</p></details>`);if(p.observationMode)texts.unshift(notice('Режим «По одному продукту» включён для удобства наблюдений. Обязательного таймера или запрета на запись других продуктов нет.'));return texts.join('');}
const onsetText={unknown:'Время относительно еды не уточнено',soon:'Во время еды или вскоре после неё',hours:'Через несколько часов',later:'Позже / на следующий день',unrelated:'Связь с едой не предполагается'};
screens.symptom=()=>{const s=p.symptoms.find(s=>s.id===editing);photoDraft=s?.photo||null;photoReading=false;photoLoadId++;triageAcknowledged='';return back('diary','К дневнику')+header('Наблюдение семьи',s?'Уточнить симптомы':'Что вы заметили?','Запись можно сохранить без указания продукта. Совпадение по времени ещё не доказывает причину.')+`<form id="symptom-form"><div class="grid2">${input('Дата','date',s?.date||TODAY,'date','required max="'+TODAY+'"')}${input('Время появления','time',s?.time||PrikormModel.localTime(),'time','required')}</div><fieldset><legend>Можно отметить несколько</legend>${Object.entries(symptomNames).map(([k,t])=>`<label class="check"><input type="checkbox" name="codes" value="${k}" ${s?.codes.includes(k)?'checked':''}><span>${t}</span></label>`).join('')}</fieldset><div id="symptom-advice" aria-live="polite"></div>${select('Когда относительно еды','onset',Object.entries(onsetText),s?.onset||'unknown')}${select('Связать с записью о еде (необязательно)','mealId',[['','Не связывать / не знаю'],...p.meals.filter(m=>m.kind==='eaten').slice().reverse().map(m=>[m.id,`${fmt(m.date)} ${m.time} · ${esc(mealTitle(m))}`])],s?.mealId||'')}<label class="field">Описание<textarea name="note" maxlength="2000" placeholder="Что произошло, как менялось состояние, какие действия предприняли">${esc(s?.note||'')}</textarea></label><label class="field">Фото для врача (необязательно)<input id="symptom-photo" type="file" accept="image/png,image/jpeg,image/webp"><small>До 8 МБ. Фото не анализируется приложением и не устанавливает диагноз.</small></label><div id="photo-preview">${photoDraft?`<div class="photo-row"><img class="photo-preview" src="${photoDraft}" alt="Прикреплённое фото"><button type="button" data-action="remove-photo">Убрать фото</button></div>`:''}</div><p class="error" id="symptom-error" role="alert"></p><button class="primary wide" type="submit">Сохранить наблюдение</button></form>`;};
function triage(codes,onset){if(codes.some(c=>['breathing','voice','collapse','severeLethargy','rapid','throat','severePain'].includes(c))||codes.includes('hives')&&codes.includes('repeatVomit'))return 'emergency';if(codes.includes('repeatVomit')&&(onset==='hours'||codes.some(c=>['pallor','lethargy'].includes(c))))return 'urgent';return '';}
function emergencyActions(){return `<div class="emergency-number"><a href="tel:112">112</a> / <a href="tel:103">103</a></div><p class="small">Экстренная помощь в России.</p><ol><li>Прекратите кормление. Не оставляйте ребёнка одного.</li><li>При подозрении на анафилаксию немедленно используйте назначенный адреналин по индивидуальному плану и вызывайте скорую. Не ждите появления сыпи или ответа врача в чате.</li><li>Уложите ребёнка, не позволяйте вставать и ходить. При затруднении дыхания допустимо положение сидя с вытянутыми ногами; при рвоте или потере сознания — на боку. Выполняйте указания диспетчера.</li></ol><p class="small">Антигистаминные и системные гормональные препараты (глюкокортикостероиды) не заменяют адреналин при анафилаксии. Их применение не должно задерживать введение адреналина и вызов скорой помощи. При пищевом энтероколите, вызванном пищевыми белками (FPIES), необходим отдельный план врача.</p>`;}
function dangerSigns(){return `<h3>Опасные признаки</h3><ul class="red-flags"><li>Затруднённое или шумное дыхание, свисты или хрипы.</li><li>Осиплость голоса, отёк языка или горла.</li><li>Обморок, резкая бледность или выраженная внезапная вялость.</li><li>Резкая сильная боль в животе.</li><li>Многократная рвота с вялостью.</li></ul>`;}
function helpContent(type='emergency'){return `<div class="eyebrow">Сначала помощь, затем запись</div><h2>${type==='urgent'?'Нужна срочная медицинская оценка':'Если появилась опасная реакция'}</h2>${type==='urgent'?'<p>Повторная рвота через несколько часов после еды, особенно с бледностью или вялостью, требует срочной медицинской оценки. Не предлагайте подозреваемый продукт повторно до консультации.</p><p>При выраженной вялости, нарушении сознания, дыхания или быстром ухудшении — немедленно вызывайте скорую.</p>':dangerSigns()}${emergencyActions()}`;}
screens.help=()=>header('План действий','Если появилась реакция')+`<section class="card emergency-card">${dangerSigns()}${emergencyActions()}</section><section class="card"><h3>Другие или отсроченные симптомы</h3><p>Прекратите текущую пробу, действуйте по письменному плану и свяжитесь с врачом. Не увеличивайте порцию и не повторяйте подозреваемый продукт до оценки врачом. При ухудшении вызывайте скорую.</p><button class="wide" data-go="diary">После оказания помощи — дополнить дневник</button><button class="link wide" data-action="new-symptom">Записать симптомы</button></section><p class="small" style="margin-top:16px">Следуйте персональному плану помощи с назначенными препаратами и дозами. Держите его доступным семье и отдельно от телефона.</p><details><summary>Повторная рвота через несколько часов после еды</summary><p>${esc(rules.get('C27').parent)}</p><p>При тяжёлом состоянии или быстром ухудшении вызывайте 112 / 103. При подозрении на энтероколит, вызванный пищевыми белками (FPIES), нужен отдельный план врача; приложение не ставит этот диагноз.</p><p class="small">${esc(rules.get('C27').evidence)}</p><p class="rule-ref"><a href="${esc(SPEC.sources.find(s=>s.id==='S16').url)}" target="_blank" rel="noopener noreferrer">Пищевой энтероколит (FPIES): рекомендации 2017</a></p></details>${ruleCard('C16')}`;
screens.safe=()=>back('more','Памятка')+header('Безопасная подача','Мягкость. Форма.<br>Внимание взрослого.')+['C20','C21','C22','C10','C11','C19'].map(id=>ruleCard(id,true)).join('');
screens.more=()=>header('Всегда под рукой','Памятка')+`<div class="stack" style="margin-top:20px"><button class="primary" data-go="readiness">Что важно перед началом</button><button data-go="safe">Безопасные формы и текстуры</button><button data-go="nutrition">Железо, разнообразие и аппетит</button><button data-go="observation">Как наблюдать за продуктами</button><button data-go="plan">Индивидуальный план врача</button><button data-go="sources">Источники и клинические правила</button><button data-go="settings">Данные и установка</button></div>`;
screens.nutrition=()=>back('more','Памятка')+header('Питание и аппетит','Железо, разнообразие<br>и спокойные приёмы пищи.')+['C03','C04','C05','C06','C07','C23'].map(id=>ruleCard(id,true)).join('')+'<button class="primary wide" data-action="iron-foods">Продукты, богатые железом</button>';
screens.observation=()=>back('more','Памятка')+header('Записи и наблюдение','Без обязательных<br>многодневных пауз.')+ruleCard('C08',true)+observationGuidance()+notice('<strong>Интервал — между новыми продуктами, а не перерыв в кормлении.</strong> Канадское педиатрическое общество (CPS) отмечает, что польза обязательных многодневных пауз не доказана. В этом дневнике нет блокирующего таймера. При симптомах не ждите окончания периода наблюдения: прекратите давать подозреваемый продукт и действуйте по плану помощи.')+`<section class="card"><label class="check"><input type="checkbox" id="observation-mode" ${p.observationMode?'checked':''}><span><strong>По одному продукту</strong>Дополнительное напоминание при записи, без блокировки других продуктов.</span></label></section>`+['C09','C13','C16','C25','C29'].map(id=>ruleCard(id)).join('');
screens.plan=()=>back('more','Памятка')+header('Решение специалиста','План — от врача.<br>Наблюдения — у вас.','Здесь можно перенести уже согласованные рекомендации. Приложение не создаёт исключающие диеты и пищевые лестницы.')+`<form id="plan-form"><label class="field">Назначение, дата и врач<textarea name="plan" maxlength="3000" rows="6" placeholder="Только готовые рекомендации врача">${esc(p.plan)}</textarea></label><fieldset><legend>Уточнение по отдельному продукту</legend>${select('Продукт','foodId',[['','Без отдельного уточнения'],...availableFoods.map(f=>[f.id,f.name])],'')}${select('Что указано врачом','doctorStatus',[['individual','Нужен индивидуальный план'],['avoid','Не предлагать до врачебной оценки']],'individual')}${input('Дата / врач / содержание рекомендации','doctorNote','')}<p class="small">Это сведения из заключения, а не вывод приложения по дневнику.</p></fieldset><label class="check"><input type="checkbox" name="confirmed" required><span>Переношу уже согласованные с врачом рекомендации.</span></label><p class="error" id="plan-error" role="alert"></p><button class="primary wide" type="submit">Сохранить план</button></form>${p.doctorFoods.map(d=>`<section class="card"><h3>${food(d.foodId).name}</h3><p class="small">Внесено как рекомендация врача: ${esc(d.note)}</p></section>`).join('')}`;
function reportAllergens(){
 const groups=[...allergenGroups];
 // Retain consumed allergens outside the main navigation groups (e.g. mustard).
 const listed=new Set(groups.flatMap(g=>g.keys));
 for(const [id,name] of Object.entries(allergenNames))if(!listed.has(id)&&eaten().some(m=>knownAllergens(m).includes(id)))groups.push({id,name,keys:[id]});
 return `<p class="small">Порядок групп соответствует странице «Аллергены». Указаны только продукты, употребление которых записано как «Ел», включая известные ингредиенты блюд. Отказ и отсутствие приёма не учитываются. Записи не подтверждают переносимость продукта или всей группы.</p><table class="report-allergens"><thead><tr><th scope="col">Аллергены и продукты</th><th scope="col">Приёмов пищи</th><th scope="col">Последний приём</th></tr></thead><tbody>${groups.map(g=>{const rows=groupMeals(g),ids=new Set(rows.flatMap(m=>m.foodIds)),items=groupFoods(g).filter(f=>ids.has(f.id));return `<tr data-report-allergen="${g.id}"><th scope="row">${esc(g.name)}${items.length?'<span class="report-foods">'+items.map(f=>esc(f.name)).join(', ')+'</span>':''}</th><td>${rows.length||'Нет записей'}</td><td>${rows.length?fmt(rows.map(m=>m.date).sort().at(-1)):'—'}</td></tr>`;}).join('')}</tbody></table>`;
}
function reportBody(){return `<div class="report-area"><div class="eyebrow">ЕмПрикорм · отчёт для врача</div><h1>${esc(p.name)}</h1><p>Дата рождения: ${esc(patientMeta(p))}</p><p class="small">Сведения семьи, не результат диагностики. Отсутствие записи не означает отсутствие продукта или реакции. </p><section class="card"><h3>Контекст и план</h3><dl class="report-context">${Object.entries({severeEczema:'Тяжёлый атопический дерматит',eggAllergy:'Установленная аллергия на яйцо',milkAllergy:'Установленная аллергия на белки коровьего молока',peanutAllergy:'Установленная аллергия на арахис',complex:'Индивидуальные особенности'}).map(([key,label])=>`<div><dt>${label}</dt><dd>${riskLabel(p.risks[key])}</dd></div>`).join('')}</dl>${p.risks.peanutReaction==='yes'?'<p class="small">В анамнезе отмечена реакция на арахис. Эта запись сама по себе не подтверждает установленную аллергию.</p>':''}<p class="plan-note">${esc(p.plan||'План не внесён')}</p>${p.doctorFoods.map(d=>'<p class="small">'+food(d.foodId).name+': '+esc(d.note)+'</p>').join('')}</section><h2>Продукты и аллергены</h2><p class="small">${eaten().filter(m=>m.unknown).length} записей об употреблении с неуточнённым составом.</p>${reportAllergens()}${p.foodReviews?.length?'<h2>Уточнения после консультации</h2>'+p.foodReviews.map(r=>'<p>'+esc(food(r.foodId).name)+' · '+fmt(r.date)+': связь прежних симптомов с продуктом исключена врачом. '+esc(r.note)+'</p>').join(''):''}<h2>Записи о еде</h2>${p.meals.length?p.meals.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(m=>mealCard(m,false)).join(''):empty('Записей нет')}<h2>Симптомы</h2>${p.symptoms.length?p.symptoms.map(s=>symptomCard(s,false)).join(''):empty('Симптомы в дневнике не записаны')}<section class="card"><h3>Вопросы врачу</h3><p class="plan-note">${esc(p.questions||'Не добавлены')}</p></section></div>`;}
const riskLabel=v=>({yes:'да',no:'не отмечено',unknown:'не уточнено'}[v]);
screens.report=()=>back('more','Памятка')+`<div class="no-print"><label class="field">Вопросы врачу<textarea id="report-questions" maxlength="2000">${esc(p.questions)}</textarea></label><label class="check"><input type="checkbox" id="include-photos" ${photoInclude?'checked':''}><span>Включить приложенные фото в отчёт</span></label><p class="small">По умолчанию фото исключены. Перед передачей проверьте содержимое.</p><div class="toolbar"><button class="primary" data-action="print-report">Печать / PDF</button><button data-action="download-report">Скачать отчёт</button></div></div><div id="report-body">${reportBody()}</div>`;
screens.sources=()=>back('more','Памятка')+header('Основания и ограничения','Почему именно так?','Редакция клинических правил 1.1 от 18 октября 2026 года.')+notice('Сведения основаны на авторской редакции клинических правил 1.1. Приложение не проходило независимую клиническую валидацию и не заменяет индивидуальный план врача. Ссылки и уровни доказательств приведены по авторской сводке.','warn')+`<h3 class="tabs-title">30 правил для проверки</h3>${SPEC.rules.map(r=>ruleCard(r.id)).join('')}<h3 class="tabs-title">Международные источники</h3>${SPEC.sources.map(s=>`<details><summary>${esc(s.short)}</summary><p>${esc(s.citation)}</p><p class="small">${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Открыть источник ↗</a></details>`).join('')}`;
screens.about=()=>back('today','Сегодня')+header('О приложении','ЕмПрикорм','Дневник знакомства с едой для семьи и её врача.')+`<div class="brand-preview"><img data-app-icon alt="Иконка ЕмПрикорм"></div><section class="card"><p>«ЕмПрикорм» помогает родителям записывать продукты и их состав, безопасную форму подачи, наблюдения и вопросы к консультации.</p><p>Не назначает сроки и дозы, не диагностирует аллергию, не подтверждает переносимость и не заменяет индивидуальный план врача.</p><p class="small">Приложение не проходило независимую клиническую валидацию.</p></section><section class="card"><h3>Дневник на вашем устройстве</h3><p>Без регистрации и облачной синхронизации. Записи не передаются автору приложения.</p><button class="wide" data-go="sources">Источники и клинические правила</button><button class="wide" data-go="settings">Данные и установка</button></section>`;
function applyIcon(){$$('[data-app-icon]').forEach(img=>{img.hidden=false;img.src=iconData;});}
function render(next=view){clearTimeout(toastTimer);$('#toast').hidden=true;view=Object.hasOwn(screens,next)?next:'today';rememberNavigation(view,p.id);const tab=({meal:'diary',symptom:'diary',food:'foods',readiness:'more',safe:'more',nutrition:'more',sources:'more',observation:'more',settings:'more',plan:'more',report:'more',profile:'more',patients:'more',help:'more',about:'more'})[view]||view;$$('.nav button').forEach(b=>{if(b.dataset.go===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderPatientSelect();$('#screen').innerHTML=screens[view]();$('#author-slot').replaceChildren($('#author-template').content.cloneNode(true));applyIcon();bind();dirty=false;const h=$('#screen h1');h?.focus({preventScroll:true});if(window.innerWidth<=760)$('#app-start').scrollIntoView({block:'start'});else window.scrollTo({top:0});}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function validDate(d){try{PrikormModel.date(d);return true;}catch{return false;}}
function chokingHelpContent(){return `<section class="choking-video-placeholder" aria-label="Видео от автора"><h3>Видео от автора</h3><p>Раздел дополнится видео об оказании помощи от автора приложения.</p></section><p>Если ребёнок не может дышать, плакать или эффективно кашлять, немедленно вызывайте скорую помощь: <a href="tel:112">112</a> или <a href="tel:103">103</a>. Включите громкую связь и выполняйте указания диспетчера с учётом возраста ребёнка.</p><p>Не пытайтесь извлечь пищу пальцами вслепую и не пытайтесь протолкнуть её водой или другой едой. Этот раздел пока не содержит полного алгоритма первой помощи.</p>`;}
function showChokingHelp(){const dialog=$('#triage-dialog'),actions=dialog.querySelector('.modal-actions');dialog.classList.add('choking-help');dialog.prepend(actions);actions.querySelector('button').classList.remove('wide');clearTimeout(toastTimer);$('#toast').hidden=true;$('#triage-body').innerHTML='<h2>Правила оказания помощи, если ребёнок подавился</h2>'+chokingHelpContent();$('#triage-dialog').setAttribute('aria-label','Правила оказания помощи, если ребёнок подавился');$('[data-action=close-triage]').textContent=returnLabel(dialog);$('#triage-dialog').showModal();$('#triage-dialog').scrollTop=0;}
function showTriage(type){const dialog=$('#triage-dialog'),actions=dialog.querySelector('.modal-actions');dialog.classList.remove('choking-help');dialog.append(actions);actions.querySelector('button').classList.add('wide');$('#triage-dialog').setAttribute('aria-label','Срочная помощь');$('[data-action=close-triage]').textContent=returnLabel(dialog);clearTimeout(toastTimer);$('#toast').hidden=true;$('#triage-body').innerHTML=helpContent(type);$('#triage-dialog').showModal();}
function symptomAdvice(codes,onset){const kind=triage(codes,onset);let t=kind?notice(kind==='emergency'?'<strong>Сначала экстренная помощь.</strong> Не ждите сохранения записи. 112 / 103.':'Повторная рвота с таким временем появления или состоянием требует срочной медицинской оценки.','danger'):'';if(codes.includes('local'))t+=notice(rules.get('C16').parent);if(codes.includes('eczema'))t+=notice(rules.get('C18').parent);if(codes.some(c=>['hives','swelling'].includes(c)))t+=notice('Не предлагайте подозреваемый продукт повторно до оценки врачом. При ухудшении или присоединении других системных симптомов вызывайте экстренную помощь.','warn');if(codes.includes('repeatVomit'))t+=notice(rules.get('C27').parent,'warn');return t;}
function bind(){
 $$('[data-group-search]').forEach(input=>input.addEventListener('input',()=>{const group=input.closest('.allergen-group');let visible=0;group.querySelectorAll('[data-allergen-food]').forEach(el=>{el.hidden=!matchesFood(food(el.dataset.allergenFood),input.value);if(!el.hidden)visible++;});group.querySelector('[data-group-count]').textContent=visible?'Найдено: '+visible:'Нет совпадений. Укажите название в записи о блюде; для рыбы можно выбрать «другой или неуточнённый вид». ';}));
 $$('#screen form input, #screen form select, #screen form textarea').forEach(el=>{el.addEventListener('input',()=>dirty=true);el.addEventListener('change',()=>dirty=true);});
 if(view==='today')$$('[data-day]').forEach(b=>b.addEventListener('click',()=>{selectedDay=b.dataset.day;$$('[data-day]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.day===selectedDay)));$('#day-detail').textContent=fmt(selectedDay)+': '+dayNames[dayState(selectedDay)];}));
 $$('[data-ready]').forEach(el=>el.addEventListener('change',()=>{p.ready[el.dataset.ready]=el.checked;persist();}));
 $('#food-search')?.addEventListener('input',e=>{search=e.target.value;$('#food-list').innerHTML=catalogRows();});
 $('#food-group')?.addEventListener('change',e=>{catalogGroup=e.target.value;$('#food-list').innerHTML=catalogRows();});
 if($('#ingredient-search')){const updateIngredients=()=>{const q=$('#ingredient-search').value;let visible=0;$$('[data-ingredient]').forEach(el=>{el.hidden=!matchesFood(food(el.dataset.ingredient),q);if(!el.hidden)visible++;});const count=$$('[name=foodIds]:checked').length;$('#ingredient-count').textContent=`Найдено: ${visible} · выбрано: ${count}. Поиск сохраняет выбранные ингредиенты.`;};$('#ingredient-search').addEventListener('input',updateIngredients);$('#meal-form').addEventListener('change',updateIngredients);updateIngredients();}

 $('#observation-mode')?.addEventListener('change',e=>{p.observationMode=e.target.checked;persist();toast('Режим наблюдения изменён. Запись продуктов остаётся доступной.');});
 if(view==='meal'){const form=$('#meal-form');function update(){const f=new FormData(form),kind=f.get('kind');$('#meal-warnings').innerHTML=mealWarnings(f.getAll('foodIds'),f.has('unknown'),kind);form.elements.result.disabled=kind!=='eaten';form.elements.amount.disabled=kind!=='eaten';}form.addEventListener('change',e=>{if(e.target.name==='foodIds'&&e.target.value==='iron-cereal'&&e.target.checked)form.elements.unknown.checked=true;update();});update();form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),kind=f.get('kind'),ids=f.getAll('foodIds'),unknown=f.has('unknown'),old=p.meals.find(m=>m.id===editing);if(!['eaten','refused','skipped'].includes(kind)){$('#meal-error').textContent='Уточните, что произошло: ребёнок ел, отказался или приёма не было.';return;}if(!validOccurrence(f.get('date'),f.get('time'))){$('#'+(view==='meal'?'meal':'symptom')+'-error').textContent='Проверьте дату и время: запись не должна относиться к будущему или к дате до рождения.';return;}if(kind!=='skipped'&&!ids.length&&!unknown){$('#meal-error').textContent='Отметьте продукты или укажите, что состав неизвестен.';return;}if(old&&kind!=='eaten'&&hasSymptoms(old)){$('#meal-error').textContent='С приёмом связана запись симптомов. Сначала уточните её связь с едой.';return;}const m={id:old?.id||uid(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),date:f.get('date'),time:f.get('time'),kind,foodIds:ids,unknown,dish:String(f.get('dish')).trim(),amount:String(f.get('amount')||'').trim(),texture:String(f.get('texture')||'').trim(),result:kind==='eaten'?f.get('result'):'unknown',note:String(f.get('note')||'').trim()};if(old)p.meals[p.meals.indexOf(old)]=m;else p.meals.push(m);editing=null;preselectedFood=null;render('diary');toast('Запись сохранена. Это не оценка переносимости.');});}
 if(view==='symptom'){const form=$('#symptom-form');function update(){const f=new FormData(form),codes=f.getAll('codes'),kind=triage(codes,f.get('onset'));$('#symptom-advice').innerHTML=symptomAdvice(codes,f.get('onset'));if(kind&&triageAcknowledged!==kind){triageAcknowledged=kind;showTriage(kind);}}form.addEventListener('change',update);update();$('#symptom-photo').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const owner=p.id,token=++photoLoadId;photoReading=true;form.querySelector('[type=submit]').disabled=true;try{const data=await readImage(file);if(!form.isConnected||p.id!==owner||token!==photoLoadId)return;photoDraft=data;$('#photo-preview').innerHTML=`<div class="photo-row"><img class="photo-preview" src="${data}" alt="Прикреплённое фото"><button type="button" data-action="remove-photo">Убрать фото</button></div>`;}catch(e){if(form.isConnected&&p.id===owner)$('#symptom-error').textContent=e.message;}finally{if(token===photoLoadId)photoReading=false;if(form.isConnected&&!storageFailed)form.querySelector('[type=submit]').disabled=false;}});form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form),codes=f.getAll('codes'),old=p.symptoms.find(s=>s.id===editing);if(!codes.length){$('#symptom-error').textContent='Отметьте хотя бы один симптом.';return;}if(!validOccurrence(f.get('date'),f.get('time'))){$('#'+(view==='meal'?'meal':'symptom')+'-error').textContent='Проверьте дату и время: запись не должна относиться к будущему или к дате до рождения.';return;}if(photoReading){$('#symptom-error').textContent='Дождитесь загрузки фото.';return;}const s={id:old?.id||uid(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),date:f.get('date'),time:f.get('time'),codes,onset:f.get('onset'),mealId:f.get('mealId')||null,note:String(f.get('note')||'').trim(),photo:photoDraft};if(old)p.symptoms[p.symptoms.indexOf(old)]=s;else p.symptoms.push(s);editing=null;photoDraft=null;render('diary');toast('Наблюдение сохранено. Причина симптомов не определяется автоматически.');});}
 $('#food-review-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),mode=data.get('reviewMode');if(mode==='excluded'){const note=String(data.get('reviewNote')).trim(),date=data.get('reviewDate'),linked=PrikormModel.relatedSymptoms(p,selectedFood);try{PrikormModel.date(date);if(p.dob&&date<p.dob||linked.some(s=>s.date>date))throw Error();}catch{$('#food-review-error').textContent='Проверьте дату заключения.';return;}if(!note){$('#food-review-error').textContent='Укажите врача и содержание заключения.';return;}if(!linked.length){$('#food-review-error').textContent='Связанных записей больше нет. Выберите отметку по дневнику.';return;}p.foodReviews=(p.foodReviews||[]).filter(r=>r.foodId!==selectedFood);p.foodReviews.push({foodId:selectedFood,date,note,symptoms:linked.map(s=>PrikormModel.reviewSnapshot(p,s))});}else p.foodReviews=(p.foodReviews||[]).filter(r=>r.foodId!==selectedFood);render('food');toast('Отметка уточнена. История симптомов сохранена.');});
 $('#plan-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('foodId'),note=String(f.get('doctorNote')).trim();if(id&&!note){$('#plan-error').textContent='Укажите содержание и источник рекомендации врача.';return;}p.plan=String(f.get('plan')).trim();if(id){p.doctorFoods=p.doctorFoods.filter(d=>d.foodId!==id);p.doctorFoods.push({foodId:id,status:f.get('doctorStatus'),note});}render('more');toast('План сохранён отдельно от семейных отметок.');});
 $('#report-questions')?.addEventListener('input',e=>{p.questions=e.target.value;persist();$('#report-body').innerHTML=reportBody();});
 $('#include-photos')?.addEventListener('change',e=>{photoInclude=e.target.checked;$('#report-body').innerHTML=reportBody();});
}
function readImage(file){return new Promise((resolve,reject)=>{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){reject(new Error('Выберите PNG, JPEG или WebP размером до 8 МБ.'));return;}const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>resolve(r.result);img.onerror=()=>reject(new Error('Не удалось открыть изображение.'));img.src=r.result;};r.onerror=()=>reject(new Error('Не удалось прочитать файл.'));r.readAsDataURL(file);});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const nav=b.dataset.go||b.dataset.food||b.dataset.patient!==undefined||b.dataset.editMeal||b.dataset.editSymptom||b.dataset.recordFood||['new-meal','new-symptom','add-patient','iron-foods'].includes(b.dataset.action);if(dirty&&nav&&b.dataset.go!=='help'&&!confirm('Форма ещё не сохранена. Перейти без сохранения?'))return;
 if(b.dataset.go){returnRequested=b.hasAttribute('data-back');render(b.dataset.go);return;}if(b.dataset.food){foodOrigin=view==='allergens'?'allergens':'foods';selectedFood=b.dataset.food;render('food');return;}if(b.dataset.filter){catalogFilter=b.dataset.filter;render('foods');return;}if(b.dataset.recordFood){preselectedFood=b.dataset.recordFood;editing=null;render('meal');return;}if(b.dataset.editMeal){editing=b.dataset.editMeal;render('meal');return;}if(b.dataset.editSymptom){editing=b.dataset.editSymptom;render('symptom');return;}if(b.dataset.patient!==undefined){selectPatient(profiles[Number(b.dataset.patient)]?.id);return;}
 switch(b.dataset.action){case 'choking-help':showChokingHelp();break;case 'new-meal':editing=null;preselectedFood=null;render('meal');break;case 'new-symptom':editing=null;render('symptom');break;case 'add-patient':render('newPatient');break;case 'iron-foods':catalogFilter='iron';catalogGroup='all';search='';render('foods');break;case 'remove-photo':photoLoadId++;photoReading=false;photoDraft=null;$('#photo-preview').replaceChildren();break;case 'close-triage':$('#triage-dialog').close();break;case 'print-report':window.print();break;case 'download-report':{const report='<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ЕмПрикорм — отчёт для врача</title><style>'+REPORT_CSS+'body{max-width:800px;margin:auto;padding:24px}</style><body>'+reportBody()+'</body></html>';download('em-prikorm-report-'+TODAY+'.html',report,'text/html;charset=utf-8');break;}}

});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});

const aboutOverlay=FamilyAbout.create({returnLabel,root:document.querySelector('.device'),trigger:'[data-go="about"]',build(){return FamilyAbout.layout({"name":"ЕмПрикорм","tagline":"Дневник знакомства с едой для семьи и её врача","icon":"./assets/icon-rounded-192.png","description":"<p>Помогает родителям записывать продукты и их состав, безопасную форму подачи, наблюдения и вопросы к консультации.</p>","details":"<p class=\"family-about-note\">Не назначает сроки и дозы, не диагностирует аллергию, не подтверждает переносимость и не заменяет индивидуальный план врача.</p>","actions":"<button type=\"button\" data-go=\"settings\">Данные и установка</button><button type=\"button\" data-go=\"sources\">Источники и клинические правила</button>",author:document.querySelector('#author-template').content.querySelector('.em-author')});},navigate(next){if(dirty&&!confirm('Изменения формы ещё не сохранены. Перейти без сохранения?'))return;render(next);}});

const helpOverlay=FamilyAbout.create({returnLabel,root:document.querySelector('.device'),id:'family-help',title:'Если появилась реакция',trigger:'[data-go="help"]',build(){const body=document.createElement('div');body.innerHTML=screens.help();body.querySelector('h1,h2')?.remove();body.querySelector('[data-action=new-symptom]')?.setAttribute('data-go','symptom');body.querySelector('[data-action=new-symptom]')?.removeAttribute('data-action');body.append(document.querySelector('#author-template').content.cloneNode(true));return body;},navigate(next){if(next===view){helpOverlay.close();return;}if(dirty&&!confirm('Изменения формы ещё не сохранены. Перейти без сохранения?'))return;if(next==='symptom')editing=null;render(next);}});
